-- GenDB engine variant Q03-wrapped_tables: template q03.sql, kind wrapped_tables (generated by generate.py; frozen)
SELECT
  l_orderkey,
  SUM(l_extendedprice * (
    1 - l_discount
  )) AS revenue,
  o_orderdate,
  o_shippriority
FROM (
  SELECT
    *
  FROM customer
) AS customer, (
  SELECT
    *
  FROM orders
) AS orders, (
  SELECT
    *
  FROM lineitem
) AS lineitem
WHERE
  c_mktsegment = $1
  AND c_custkey = o_custkey
  AND l_orderkey = o_orderkey
  AND o_orderdate < $2
  AND l_shipdate > $2
GROUP BY
  l_orderkey,
  o_orderdate,
  o_shippriority
ORDER BY
  revenue DESC,
  o_orderdate
LIMIT 10
